import unittest

def cost(quantity):
    if quantity < 0:
        raise ValueError("negative quantity")
    return quantity * 4

class CostTests(unittest.TestCase):
    def test_cost(self):
        self.assertEqual(cost(3), 12)
        self.assertTrue(cost(3) > 0)
    def test_invalid_quantity(self):
        with self.assertRaises(ValueError):
            cost(-1)

