    def release():
        resource_events.append("release")
class QuantityTests(unittest.TestCase):

    def setUp(self):
        acquire()
        self.addCleanup(release)
        self.quantities = [3, 2]

    def test_mutation(self):
        self.assertEqual(self.quantities, [3, 2])
        self.quantities[0] = 0

    def test_fresh_state(self):
        self.assertEqual(self.quantities, [3, 2])
